def main():
    existing=persistence.load_blogs(); titles={(p.get("title") or "").strip().lower() for p in existing}; added=0
    for i, post in enumerate(POSTS):
        if post["title"].strip().lower() in titles:
            print("SKIP:", post["title"]); continue
        new=dict(post); new.update({"id":str(int(time.time()*1000)+i),"author":AUTHOR,"updated_date":post["publish_date"],"date":post["publish_date"],"published":True})
        existing.insert(0,new); titles.add(post["title"].strip().lower()); added+=1; print("ADD:",post["title"],"->",post["publish_date"])
    if added: persistence.save_blogs(existing)
    print("Done. Added",added,"scheduled posts.")
if __name__=="__main__": main()